type Product = {
  id: string; name: string; category: string; aisle: string;
  price: number; stock: number; unit: string; tags: string[];
};
type Filters = {
  query?: string; category?: string; aisle?: string;
  min_price?: number; max_price?: number; in_stock_only?: boolean;
};

function encodeFrame(value: unknown): Buffer {
  const payload = Buffer.from(JSON.stringify(value));
  const frame = Buffer.allocUnsafe(6 + payload.length);
  frame.writeUInt32LE(payload.length, 0);
  frame.writeUInt16LE(protocolVersion, 4);
  payload.copy(frame, 6);
  return frame;
}

function decodeFrame(buffer: Buffer): { frame: any; rest: Buffer } | null {
  if (buffer.length < 6) return null;
  const length = buffer.readUInt32LE(0);
  if (buffer.readUInt16LE(4) !== protocolVersion) throw new Error("unsupported Silc protocol");
  if (buffer.length < 6 + length) return null;
  return { frame: JSON.parse(buffer.subarray(6, 6 + length).toString()), rest: buffer.subarray(6 + length) };
}

let supervisor: Socket | null = null;
let pending = Buffer.alloc(0);
const waiters = new Map<string, { resolve: (value: any) => void; reject: (error: Error) => void }>();

function dispatchFrames() {
  while (true) {
    const decoded = decodeFrame(pending);
    if (!decoded) return;
    pending = decoded.rest;
    if (decoded.frame.type === "RESPONSE" && typeof decoded.frame.request_id === "string") {
      const waiter = waiters.get(decoded.frame.request_id);
      if (waiter) {
        waiters.delete(decoded.frame.request_id);
        waiter.resolve(decoded.frame);
      }
    }
  }
}

function connectSupervisor(): Promise<void> {
  return new Promise((resolve, reject) => {
    supervisor = connect(socketPath);
    supervisor.on("connect", () => {
      supervisor!.write(encodeFrame({ type: "HELLO", worker_id: "bun", role: "bun", abi_version: abiVersion, pid: process.pid }));
      supervisor!.write(encodeFrame({ type: "READY", worker_id: "bun" }));
      resolve();
    });
    supervisor.on("data", (chunk) => {
      pending = Buffer.concat([pending, chunk]);
      try { dispatchFrames(); } catch (error) {
        for (const waiter of waiters.values()) waiter.reject(error instanceof Error ? error : new Error(String(error)));
        waiters.clear();
      }
    });
    supervisor.on("error", reject);
  });
}

function complete(prompt: string): Promise<any> {
  if (!supervisor) return Promise.reject(new Error("supervisor socket not connected"));
  const requestId = crypto.randomUUID();
  return new Promise((resolve, reject) => {
    waiters.set(requestId, { resolve, reject });
    supervisor!.write(encodeFrame({ type: "INGEST", request_id: requestId, author: "inventory", text: prompt }));
  });
}

function readProducts(): Product[] {
  const db = new Database(dbPath, { readonly: true });
  try {
    return (db.query("SELECT id,name,category,aisle,price,stock,unit,tags FROM products ORDER BY category,name").all() as any[])
      .map((row) => ({ ...row, price: Number(row.price), stock: Number(row.stock), tags: JSON.parse(String(row.tags || "[]")) }));
  } finally { db.close(); }
}

function applyFilters(products: Product[], filters: Filters): Product[] {
  const query = String(filters.query || "").trim().toLowerCase();
  return products.filter((product) => {
    const haystack = [product.name, product.category, product.aisle, product.unit, ...product.tags].join(" ").toLowerCase();
    return (!query || haystack.includes(query))
      && (!filters.category || product.category.toLowerCase() === String(filters.category).toLowerCase())
      && (!filters.aisle || product.aisle.toLowerCase() === String(filters.aisle).toLowerCase())
      && (filters.min_price == null || product.price >= Number(filters.min_price))
      && (filters.max_price == null || product.price <= Number(filters.max_price))
      && (!filters.in_stock_only || product.stock > 0);
  });
}

function filtersFromUrl(url: URL): Filters {
  const number = (name: string) => url.searchParams.has(name) ? Number(url.searchParams.get(name)) : undefined;
  return {
    query: url.searchParams.get("query") || undefined,
    category: url.searchParams.get("category") || undefined,
    aisle: url.searchParams.get("aisle") || undefined,
    min_price: number("min_price"),
    max_price: number("max_price"),
    in_stock_only: ["1", "true", "yes"].includes((url.searchParams.get("in_stock_only") || "").toLowerCase()),
  };
}

function parseFilterJson(reply: string): Filters {
  const match = reply.match(/\{[\s\S]*\}/);
  if (!match) throw new Error("model did not return filter JSON");
  const value = JSON.parse(match[0]);
  const filters: Filters = {};
  if (typeof value.query === "string") filters.query = value.query.slice(0, 120);
  if (typeof value.category === "string") filters.category = value.category.slice(0, 80);
  if (typeof value.aisle === "string") filters.aisle = value.aisle.slice(0, 40);
  if (Number.isFinite(value.min_price)) filters.min_price = Number(value.min_price);
  if (Number.isFinite(value.max_price)) filters.max_price = Number(value.max_price);
  if (typeof value.in_stock_only === "boolean") filters.in_stock_only = value.in_stock_only;
  return filters;
}

function fallbackFilters(query: string): Filters {
  const lower = query.toLowerCase();
  const filters: Filters = {};
  for (const category of ["Produce", "Dairy", "Bakery", "Pantry", "Frozen", "Beverages", "Snacks"]) {
    if (lower.includes(category.toLowerCase())) filters.category = category;
  }
  const aisle = lower.match(/\baisle\s+([a-z0-9-]+)/);
  if (aisle) filters.aisle = aisle[1];
  const under = lower.match(/\b(?:under|below|less than)\s+\$?(\d+(?:\.\d+)?)/);
  if (under) filters.max_price = Number(under[1]);
  const over = lower.match(/\b(?:over|above|more than)\s+\$?(\d+(?:\.\d+)?)/);
  if (over) filters.min_price = Number(over[1]);
  if (/\bin stock\b|\bavailable\b/.test(lower)) filters.in_stock_only = true;
  if (!Object.keys(filters).length) filters.query = query;
  return filters;
}

function compactScope(products: Product[]): string {
  return products.slice(0, 30).map((p) =>
    `${p.name} | ${p.category} | aisle ${p.aisle} | $${p.price.toFixed(2)} | stock ${p.stock} | ${p.unit}`
  ).join("\n").slice(0, 6000);
}

function contentType(pathname: string): string {
  if (pathname.endsWith(".js")) return "application/javascript; charset=utf-8";
  if (pathname.endsWith(".css")) return "text/css; charset=utf-8";
  if (pathname.endsWith(".html")) return "text/html; charset=utf-8";
  return "application/octet-stream";
}

async function serveAsset(pathname: string): Promise<Response | null> {
  const rel = pathname.replace(/^\/assets\//, "");
  if (!rel || rel.includes("..") || rel.includes("\\")) return new Response("Not found", { status: 404 });
  const file = Bun.file(join(distDir, rel));
  if (!(await file.exists())) return null;
  return new Response(file, { headers: { "content-type": contentType(rel) } });
}

const thoughtPivotAscii = [
  "  _______ ____",
  " /_  __// __ \\",
  "  / /  / /_/ /",
  " /_/  / ____/",
  "     /_/",
].join("\r\n");

type TerminalSession = { buffer: string; visible: Product[]; filters: Filters; waiting: boolean };

function showProducts(products: Product[]): string {
  if (!products.length) return "No matching products.\r\n";
  return products.map((p) =>
    `${p.name.padEnd(24)} ${p.category.padEnd(12)} aisle ${p.aisle.padEnd(3)} $${p.price.toFixed(2).padStart(6)}  stock ${String(p.stock).padStart(2)}`
  ).join("\r\n") + "\r\n";
}

function parseTerminalFilters(text: string): Filters {
  const filters: Filters = {};
  for (const token of text.match(/(?:[^\s"]+|"[^"]*")+/g) || []) {
    const [key, ...parts] = token.split("=");
    const value = parts.join("=").replace(/^"|"$/g, "");
    if (!value) continue;
    if (key === "query" || key === "category" || key === "aisle") filters[key] = value;
    if (key === "min_price" || key === "max_price") filters[key] = Number(value);
    if (key === "in_stock_only") filters.in_stock_only = ["1", "true", "yes"].includes(value.toLowerCase());
  }
  return filters;
}

function startTerminalServer() {
  if (terminalPort <= 0) return;
  Bun.listen<TerminalSession>({
    hostname: "127.0.0.1",
    port: terminalPort,
    socket: {
      open(socket) {
        const products = readProducts();
        socket.data = { buffer: "", visible: products, filters: {}, waiting: false };
        socket.write("\x1b[2J\x1b[H" + `\x1b[38;2;184;115;51m${thoughtPivotAscii}\x1b[0m\r\n`
          + "\x1b[1mTHOUGHTPIVOT\x1b[0m / SILC\r\n----------------------------------------\r\n"
          + "Grocery Inventory\r\nCommands: /list, /filter key=value…, /search query, /chat question, /visible, /quit\r\n\r\ninventory> ");
      },
      data(socket, data) {
        socket.data.buffer += new TextDecoder().decode(data).replace(/\0/g, "");
        const lines = socket.data.buffer.split(/\r?\n/);
        socket.data.buffer = lines.pop() || "";
        for (const raw of lines) {
          const line = raw.replace(/[\b\x7f]/g, "").trim();
          if (!line) { socket.write("inventory> "); continue; }
          if (line === "/quit" || line === "/exit") { socket.write("Goodbye.\r\n"); socket.end(); return; }
          if (socket.data.waiting) continue;
          if (line === "/list") socket.data.visible = readProducts();
          else if (line === "/visible") { socket.write(showProducts(socket.data.visible)); socket.write("inventory> "); continue; }
          else if (line.startsWith("/filter ")) {
            socket.data.filters = parseTerminalFilters(line.slice(8));
            socket.data.visible = applyFilters(readProducts(), socket.data.filters);
          } else if (line.startsWith("/search ")) {
            socket.data.waiting = true;
            const query = line.slice(8);
            const prompt = `Return only JSON using keys query, category, aisle, min_price, max_price, in_stock_only. Omit unknown keys. Inventory categories: Produce, Dairy, Bakery, Pantry, Frozen, Beverages, Snacks. Request: ${query}`;
            void complete(prompt).then((response) => {
              try {
                socket.data.filters = parseFilterJson(response.reply || "");
              } catch {
                socket.data.filters = fallbackFilters(query);
              }
              socket.data.visible = applyFilters(readProducts(), socket.data.filters);
              socket.write(showProducts(socket.data.visible));
            }).catch((error) => socket.write(`Error: ${String(error)}\r\n`)).finally(() => {
              socket.data.waiting = false; socket.write("inventory> ");
            });
            continue;
          } else if (line.startsWith("/chat ")) {
            socket.data.waiting = true;
            const question = line.slice(6);
            const prompt = `Answer only from the visible grocery products below. If the answer is absent, say so. Be concise.\n\n${compactScope(socket.data.visible)}\n\nQuestion: ${question}`;
            void complete(prompt).then((response) => socket.write(`${response.reply || ""}\r\n`))
              .catch((error) => socket.write(`Error: ${String(error)}\r\n`)).finally(() => {
                socket.data.waiting = false; socket.write("inventory> ");
              });
            continue;
          } else if (!line.startsWith("/")) { socket.write("Use /list, /filter, /search, /chat, /visible, or /quit.\r\ninventory> "); continue; }
          else if (line !== "/list") { socket.write("Unknown command.\r\ninventory> "); continue; }
          socket.write(showProducts(socket.data.visible));
          socket.write("inventory> ");
        }
      },
      error(socket, error) { console.error("inventory terminal error", error); socket.end(); },
    },
  });
  console.log(`SILC_TERMINAL_READY telnet://127.0.0.1:${terminalPort}`);
}

await connectSupervisor();

Bun.serve({
  hostname: "127.0.0.1",
  port,
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method === "GET" && (url.pathname === route || url.pathname === "/")) {
      const index = Bun.file(join(distDir, "index.html"));
      if (!(await index.exists())) return new Response("Silc ui::web bundle missing — run silc build", { status: 500 });
      return new Response(index, { headers: { "content-type": "text/html; charset=utf-8" } });
    }
    if (request.method === "GET" && url.pathname.startsWith("/assets/")) {
      return (await serveAsset(url.pathname)) || new Response("Not found", { status: 404 });
    }
    if (request.method === "GET" && url.pathname === "/health") {
      return Response.json({ ok: true, ui: "web", profile: "inventory", substrate: "react" });
    }
    if (request.method === "GET" && url.pathname === "/products") {
      try {
        const products = applyFilters(readProducts(), filtersFromUrl(url));
        return Response.json({ ok: true, count: products.length, products }, { headers: { "cache-control": "no-store" } });
      } catch (error) { return Response.json({ error: String(error) }, { status: 500 }); }
    }
    if (request.method === "POST" && url.pathname === "/ai_search") {
      try {
        const body = await request.json() as { query?: string };
        const query = String(body.query || "").trim().slice(0, 500);
        if (!query) return Response.json({ error: "query is required" }, { status: 400 });
        const prompt = `Return only a JSON object with any applicable keys: query (string), category (string), aisle (string), min_price (number), max_price (number), in_stock_only (boolean). Omit unknown keys. Categories: Produce, Dairy, Bakery, Pantry, Frozen, Beverages, Snacks. Natural-language request: ${query}`;
        const response = await complete(prompt);
        let filters: Filters;
        try {
          filters = parseFilterJson(response.reply || "");
        } catch {
          filters = fallbackFilters(query);
        }
        const products = applyFilters(readProducts(), filters);
        return Response.json({ ...response, filters, count: products.length });
      } catch (error) { return Response.json({ error: String(error) }, { status: 500 }); }
    }
    if (request.method === "POST" && url.pathname === "/complete") {
      try {
        const body = await request.json() as { prompt?: string; visible_products?: Product[] };
        const question = String(body.prompt || "").trim().slice(0, 2000);
        if (!question) return Response.json({ error: "prompt is required" }, { status: 400 });
        const allowedIds = new Set(readProducts().map((product) => product.id));
        const visible = (Array.isArray(body.visible_products) ? body.visible_products : [])
          .filter((product) => product && allowedIds.has(String(product.id))).slice(0, 30);
        const prompt = `Answer only from the visible grocery products below. If the answer is not in this context, say you cannot determine it. Be concise.\n\n${compactScope(visible)}\n\nQuestion: ${question}`;
        const response = await complete(prompt);
        return Response.json({ ...response, visible_count: visible.length }, { status: response.ok ? 201 : 500 });
      } catch (error) { return Response.json({ error: String(error) }, { status: 500 }); }
    }
    return new Response("Not found", { status: 404 });
  },
});

